from collections import Counter, deque

def canSplitChains(nums, minLen):
    cnt = Counter(nums)
    open_ = deque()          # [start value, number of chains] for chains ending at prev
    prev = None
    prev_cnt = 0
    for x in sorted(cnt):
        c = cnt[x]
        if prev is not None and x != prev + 1:
            for s, m in open_:
                if prev - s + 1 < minLen:
                    return False
            open_.clear()
            prev_cnt = 0
        p = prev_cnt
        if c > p:
            open_.append([x, c - p])
        elif c < p:
            need = p - c
            while need:
                s, m = open_[0]
                if x - s < minLen:
                    return False
                t = min(m, need)
                if t == m:
                    open_.popleft()
                else:
                    open_[0][1] -= t
                need -= t
        prev = x
        prev_cnt = c
    for s, m in open_:
        if prev - s + 1 < minLen:
            return False
    return True
